}

after.content:
    Files.createDirectories(objects);
    Files.createDirectories(uploads);
    loadState();
    cleanupIncomplete(clock.instant());
} catch (IOException failure) {
    throw error("artifact.store_unavailable", Map.of(), failure);
}
